#!/usr/bin/env python3
"""Wave-37h single-lane candidate (generated by gen_wave37h.py)."""
import numpy as np

M64 = (1 << 64) - 1
SCHED = [(30, 41, [39, 51, 25]), (51, 39, [15, 14, 37]), (47, 8, [31, 24, 48]), (52, 53, [18, 42, 63]), (34, 33, [28, 36, 29])]


def _rotl(v, r):
    r &= 63
    if r == 0:
        return v & M64
    return ((v << r) | (v >> (64 - r))) & M64


def mix(xs, k):
    xs = np.asarray(xs, dtype=np.uint64)
    k = np.asarray(k, dtype=np.uint64)
    x = (xs ^ k) & M64
    for a, b, lins in SCHED:
        v = x ^ (_rotl(x, a) & _rotl(x, b))
        for c in lins:
            v ^= _rotl(x, c)
        x = v & M64
    return (x ^ _rotl(k, 13)) & M64
